export const kitchenLineHtml = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<style>:root{color-scheme:light}body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style>\n<title>Kitchen Line</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@700;800&family=Hanken+Grotesk:wght@400;500;600;700&display=swap\">\n<style>\n/* Layout: a tall portrait court scaled to the viewport, beside a scoreboard column; stacks on phones.\n   Look: court-side signage. Condensed display numerals, optic-yellow ball, paddle-coral accent. */\n:root{\n  --bg:#E8EDF1;\n  --panel:#F7F9FB;\n  --ink:#10202E;\n  --ink-2:#506274;\n  --line:#CBD5DE;\n  --accent:#D13B1F;\n  --on-accent:#FFFFFF;\n  --ball:#DDEB2D;\n  --ball-ink:#6F7A0A;\n  --kbd:#E1E8EE;\n  --seg-on:#10202E;\n  --seg-on-ink:#F7F9FB;\n  --font-display:'Big Shoulders Display','Arial Narrow',Impact,sans-serif;\n  --font-body:'Hanken Grotesk',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#0B131B; --panel:#13202D; --ink:#E7EEF5; --ink-2:#9FB1C2; --line:#25384B;\n    --accent:#FF7455; --on-accent:#220C06; --ball:#E4F23A; --ball-ink:#E4F23A;\n    --kbd:#1C2D3E; --seg-on:#E7EEF5; --seg-on-ink:#0B131B; color-scheme:dark;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#0B131B; --panel:#13202D; --ink:#E7EEF5; --ink-2:#9FB1C2; --line:#25384B;\n  --accent:#FF7455; --on-accent:#220C06; --ball:#E4F23A; --ball-ink:#E4F23A;\n  --kbd:#1C2D3E; --seg-on:#E7EEF5; --seg-on-ink:#0B131B; color-scheme:dark;\n}\n\n*,*::before,*::after{box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font-family:var(--font-body);font-size:15px;line-height:1.45}\nbutton{font-family:inherit}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n\n.page{max-width:1160px;margin:0 auto;padding-inline:16px;padding-block:20px 36px}\n\n.top{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:14px 24px;margin-bottom:18px}\n.kicker{font:600 12px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2)}\nh1{font:800 clamp(42px,8vw,68px)/.88 var(--font-display);letter-spacing:.01em;text-transform:uppercase;margin:10px 0 0;text-wrap:balance}\n.opts{display:flex;flex-wrap:wrap;gap:10px;align-items:center}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:8px;overflow:hidden;background:var(--panel)}\n.seg button{appearance:none;border:0;background:transparent;color:var(--ink);font:600 13px/1 var(--font-body);padding:10px 14px;cursor:pointer}\n.seg button + button{border-left:1px solid var(--line)}\n.seg button[aria-pressed=\"true\"]{background:var(--seg-on);color:var(--seg-on-ink)}\n.chip{appearance:none;border:1px solid var(--line);background:var(--panel);color:var(--ink);font:600 13px/1 var(--font-body);padding:10px 14px;border-radius:8px;cursor:pointer}\n.chip[aria-pressed=\"false\"]{color:var(--ink-2)}\n\n.layout{display:grid;gap:16px;grid-template-columns:minmax(0,1fr);grid-template-areas:\"score\" \"court\" \"pad\" \"info\"}\n.score{grid-area:score}\n.court-box{grid-area:court;justify-self:center;position:relative;line-height:0;max-width:100%}\n.pad{grid-area:pad}\n.info{grid-area:info}\n@media (min-width:880px){\n  .layout{grid-template-columns:auto minmax(300px,420px);grid-template-areas:\"court score\" \"court pad\" \"court info\";grid-template-rows:auto auto 1fr;justify-content:center;column-gap:36px;align-items:start}\n}\n\n.panel{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:16px;min-width:0}\n.panel h2{font:700 12px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2);margin:0 0 12px}\n\n.row{display:grid;grid-template-columns:14px 1fr auto auto;align-items:center;column-gap:10px;padding-block:6px}\n.row + .row{border-top:1px solid var(--line)}\n.swatch{width:14px;height:14px;border-radius:50%}\n.swatch.you{background:#E8553A}\n.swatch.cpu{background:#EDF2F7;box-shadow:inset 0 0 0 2px #1E4C6E}\n.name{font:700 15px/1.2 var(--font-body)}\n.serving{display:inline-flex;align-items:center;gap:6px;font:700 11px/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-2);opacity:0}\n.serving::before{content:\"\";width:10px;height:10px;border-radius:50%;background:var(--ball);box-shadow:0 0 0 1.5px var(--ball-ink)}\n.row[data-serving=\"true\"] .serving{opacity:1}\n.num{font:800 72px/.9 var(--font-display);font-variant-numeric:tabular-nums;min-width:1.1ch;text-align:right}\n.meta{display:flex;flex-wrap:wrap;gap:6px 20px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line);color:var(--ink-2);font-size:13px}\n.meta b{color:var(--ink);font-variant-numeric:tabular-nums}\n\ncanvas{display:block;border-radius:10px;touch-action:none;cursor:crosshair;max-width:100%}\n.banner{position:absolute;left:50%;top:34%;transform:translateX(-50%);width:max-content;max-width:86%;text-align:center;line-height:1.35;pointer-events:none;background:rgba(9,20,31,.8);color:#F4F8FB;padding:12px 18px;border-radius:10px}\n.b-title{font:800 clamp(30px,6vw,44px)/.95 var(--font-display);letter-spacing:.03em;text-transform:uppercase}\n.b-sub{font:500 13px/1.4 var(--font-body);margin-top:6px;color:#C9D6E2}\n.hint{position:absolute;left:50%;bottom:12px;transform:translateX(-50%);max-width:90%;text-align:center;pointer-events:none;background:rgba(9,20,31,.82);color:#F4F8FB;font:600 13px/1.3 var(--font-body);padding:8px 12px;border-radius:8px}\n\n.pad{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.btn{appearance:none;border:1.5px solid var(--ink);background:var(--panel);color:var(--ink);border-radius:10px;min-height:68px;padding:10px 12px;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;touch-action:manipulation;-webkit-tap-highlight-color:transparent;user-select:none}\n.btn .b-t{font:800 28px/1 var(--font-display);letter-spacing:.05em;text-transform:uppercase}\n.btn .b-s{font:500 12px/1.2 var(--font-body);opacity:.78}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn:active{transform:translateY(1px)}\n\n.info ul{margin:0 0 18px;padding:0;list-style:none;display:grid;gap:10px}\n.info li{font-size:14px;color:var(--ink-2)}\n.info li b{color:var(--ink)}\n.ctl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:8px 14px;font-size:14px}\n.ctl dt{font-weight:700}\n.ctl dd{margin:0;color:var(--ink-2);min-width:0}\nkbd{font:600 12px/1 var(--font-body);background:var(--kbd);border:1px solid var(--line);border-bottom-width:2px;border-radius:5px;padding:2px 6px;white-space:nowrap}\n\n.score,.pad{touch-action:none;-webkit-user-select:none;user-select:none}\ncanvas{-webkit-touch-callout:none}\n/* Pause sits in the green margin at the court's upper left, above the Paused veil. */\n.pause{position:absolute;z-index:2;top:4px;left:4px;width:36px;height:36px;padding:0;display:flex;align-items:center;justify-content:center;gap:4px;appearance:none;border:1px solid rgba(244,248,251,.35);background:rgba(9,20,31,.55);border-radius:8px;cursor:pointer;touch-action:manipulation}\n.pause i{display:block;width:4px;height:14px;border-radius:2px;background:#F4F8FB}\n.pause[aria-pressed=\"true\"]{background:#F4F8FB;border-color:#F4F8FB}\n.pause[aria-pressed=\"true\"] i{background:#10202E}\n.veil{position:absolute;inset:0;border-radius:10px;background:rgba(9,20,31,.68);color:#F4F8FB;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;line-height:1.35;padding:16px;cursor:pointer}\n.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\n.net-on [data-cpu-only]{display:none!important}\n/* Online lobby: a card floating over the court. */\n.lobby{position:absolute;z-index:6;inset:0;border-radius:10px;background:rgba(9,20,31,.74);display:flex;align-items:center;justify-content:center;padding:16px;line-height:1.4}\n.lob-card{width:min(340px,100%);background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:14px;box-shadow:0 12px 32px rgba(9,20,31,.35)}\n.lob-head{display:flex;align-items:center;justify-content:space-between;gap:12px}\n.lob-head .b-title{font-size:34px}\n.lob-x{appearance:none;border:1px solid var(--line);background:var(--bg);color:var(--ink);width:34px;height:34px;border-radius:8px;font:600 20px/1 var(--font-body);cursor:pointer}\n.lob-sec{display:flex;flex-direction:column;gap:10px}\n.lob-lbl{font:700 11px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2)}\n.lob-in{appearance:none;width:100%;min-width:0;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:11px 12px;font:600 15px/1.2 var(--font-body)}\n.lob-in.code{font:800 24px/1 var(--font-display);letter-spacing:.24em;text-transform:uppercase;text-align:center}\n.lob-in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.lob-btn{appearance:none;border:1.5px solid var(--ink);background:var(--panel);color:var(--ink);border-radius:10px;min-height:46px;padding:0 16px;font:800 20px/1 var(--font-display);letter-spacing:.06em;text-transform:uppercase;cursor:pointer}\n.lob-btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.lob-btn:disabled{opacity:.55;cursor:progress}\n.lob-join{display:grid;grid-template-columns:1fr auto;gap:8px}\n.lob-or{display:flex;align-items:center;gap:10px;color:var(--ink-2);font:600 12px/1 var(--font-body);letter-spacing:.1em;text-transform:uppercase}\n.lob-or::before,.lob-or::after{content:\"\";flex:1;height:1px;background:var(--line)}\n.lob-p{margin:0;font-size:14px;color:var(--ink-2)}\n.lob-err{margin:0;font-size:13px;color:var(--accent);min-height:1em}\n.lob-err:empty{display:none}\n.lob-code{font:800 64px/1 var(--font-display);letter-spacing:.16em;text-align:center;padding:10px 0 6px;font-variant-numeric:tabular-nums;user-select:all}\n.lob-link{appearance:none;border:0;background:none;color:var(--ink-2);font:600 13px/1 var(--font-body);text-decoration:underline;text-underline-offset:3px;cursor:pointer;padding:6px;align-self:center}\n.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ball);box-shadow:0 0 0 1.5px var(--ball-ink);margin-right:8px;animation:kl-pulse 1.2s ease-in-out infinite}\n@keyframes kl-pulse{50%{opacity:.25}}\n@media (prefers-reduced-motion:reduce){.dot{animation:none}}\n.auto-chip{display:none}\n.menu-btn,.pill,.stick,.stick-hint{display:none}\n.btn .b-s.m{display:none}\n.btn{position:relative;overflow:hidden;touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}\n.btn::after{content:\"\";position:absolute;inset:0;background:currentColor;opacity:.2;transform-origin:50% 100%;transform:scaleY(var(--c,0));pointer-events:none}\n@media (max-width:879px),(pointer:coarse){\n  .auto-chip{display:inline-block}\n}\n/* Phone layout: slim top bar, full-width court with a floating score pill, and a light deck with a stick on the left and Dink + Drive on the right. */\n@media (max-width:879px){\n  html,body{height:100%;overflow:hidden;overscroll-behavior:none}\n  .page{padding:0;height:100dvh;overflow:hidden}\n  .top{position:relative;flex-wrap:nowrap;align-items:center;margin:0;height:56px;padding:0 12px;gap:12px;background:var(--panel);border-bottom:1px solid var(--line)}\n  .top > div:first-child{flex:1;min-width:0}\n  .kicker{display:none}\n  h1{font-size:28px;margin:0;line-height:1}\n  .menu-btn{display:flex;flex:none;width:40px;height:40px;padding:0;appearance:none;border:1px solid var(--line);border-radius:10px;background:var(--bg);flex-direction:column;align-items:center;justify-content:center;gap:4px;cursor:pointer}\n  .menu-btn i{display:block;width:18px;height:3px;border-radius:2px;background:var(--ink)}\n  .opts{display:none;position:absolute;z-index:5;right:12px;top:60px;max-width:calc(100% - 24px);padding:12px;gap:8px;background:var(--panel);border:1px solid var(--line);border-radius:12px;box-shadow:0 8px 24px rgba(9,20,31,.25)}\n  .top.open .opts{display:flex}\n  .seg button,.chip{padding:10px 12px;font-size:13px}\n  .layout{display:flex;flex-direction:column;gap:0;height:calc(100dvh - 56px);background:#2E6B58}\n  .score{display:none}\n  .court-box{align-self:stretch;width:100%;display:flex;justify-content:center;background:#2E6B58}\n  .court-box canvas{border-radius:0}\n  .veil{border-radius:0}\n  .pause{top:12px;left:12px;width:40px;height:40px}\n  .pill{display:flex;position:absolute;z-index:2;top:12px;left:50%;transform:translateX(-50%);height:40px;padding:0 16px;align-items:center;gap:9px;border-radius:20px;border:1px solid rgba(244,248,251,.35);background:rgba(9,20,31,.62);color:#F4F8FB;line-height:1;pointer-events:none}\n  .pill b{font:800 28px/1 var(--font-display);font-variant-numeric:tabular-nums}\n  .pill .sep{width:1px;height:18px;background:rgba(244,248,251,.4)}\n  .pill .sw{width:10px;height:10px;border-radius:50%}\n  .pill .sw.you{background:#E8553A}\n  .pill .sw.cpu{background:#EDF2F7;box-shadow:inset 0 0 0 2px #1E4C6E}\n  .pill .sv{width:8px;height:8px;border-radius:50%;background:#E4F23A;opacity:0}\n  .pill .sv.on{opacity:1}\n  .pad{position:fixed;left:0;right:0;bottom:0;height:0;display:block;padding:0;background:none;border:0;pointer-events:none}\n  .stick-hint{display:flex;position:fixed;left:20px;bottom:calc(24px + env(safe-area-inset-bottom));width:96px;height:96px;border-radius:50%;border:2px dashed rgba(244,248,251,.4);align-items:center;justify-content:center;font:600 11px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:rgba(244,248,251,.55);pointer-events:none}\n  .stick-hint.off{display:none}\n  .stick{position:fixed;z-index:4;width:112px;height:112px;margin:-56px 0 0 -56px;border-radius:50%;border:2px solid rgba(244,248,251,.5);background:rgba(9,20,31,.35);pointer-events:none}\n  .stick.on{display:block}\n  .knob{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px 0 0 -26px;border-radius:50%;background:rgba(244,248,251,.88);box-shadow:0 2px 0 rgba(0,0,0,.3);pointer-events:none;will-change:transform}\n  .btn{position:absolute;z-index:3;border-radius:50%;min-height:0;padding:0;pointer-events:auto;background:rgba(247,249,251,.9)}\n  .btn.primary{background:rgba(209,59,31,.92)}\n  #btnDink{width:72px;height:72px;right:116px;bottom:calc(22px + env(safe-area-inset-bottom))}\n  #btnDrive{width:92px;height:92px;right:14px;bottom:calc(30px + env(safe-area-inset-bottom))}\n  .btn .b-t{font-size:22px}\n  #btnDrive .b-t{font-size:26px}\n  .btn .b-s.d{display:none}\n  .btn .b-s.m{display:block;font-size:9px}\n  .banner{padding:10px 12px;max-width:92%}\n  .b-sub{font-size:12px}\n  .hint{font-size:12px}\n  .info{display:none}\n}\n</style>\n</head>\n<body>\n\n<main class=\"page\">\n  <header class=\"top\">\n    <div>\n      <div class=\"kicker\">Singles · first to 11 · win by 2</div>\n      <h1>Kitchen Line</h1>\n    </div>\n    <div class=\"opts\" id=\"opts\">\n      <button type=\"button\" class=\"chip\" id=\"btnOnline\">Play online</button>\n      <div class=\"seg\" role=\"group\" aria-label=\"CPU level\" data-cpu-only>\n        <button type=\"button\" data-diff=\"easy\" aria-pressed=\"false\">Easy</button>\n        <button type=\"button\" data-diff=\"medium\" aria-pressed=\"true\">Medium</button>\n        <button type=\"button\" data-diff=\"hard\" aria-pressed=\"false\">Hard</button>\n      </div>\n      <button type=\"button\" class=\"chip auto-chip\" id=\"btnAuto\" aria-pressed=\"true\">Auto swing on</button>\n      <button type=\"button\" class=\"chip\" id=\"btnSound\" aria-pressed=\"true\">Sound on</button>\n      <button type=\"button\" class=\"chip\" id=\"btnNew\">New game</button>\n    </div>\n    <button type=\"button\" class=\"menu-btn\" id=\"btnMenu\" aria-label=\"Menu\" aria-expanded=\"false\" aria-controls=\"opts\"><i></i><i></i><i></i></button>\n  </header>\n\n  <div class=\"layout\" id=\"layout\">\n    <section class=\"panel score\" id=\"scoreBox\" aria-label=\"Scoreboard\">\n      <div class=\"row\" id=\"rowYou\" data-serving=\"true\">\n        <span class=\"swatch you\"></span><span class=\"name\">You</span><span class=\"serving\">Serving</span><span class=\"num\" id=\"sYou\">0</span>\n      </div>\n      <div class=\"row\" id=\"rowCpu\" data-serving=\"false\">\n        <span class=\"swatch cpu\"></span><span class=\"name\" id=\"nameCpu\">CPU</span><span class=\"serving\">Serving</span><span class=\"num\" id=\"sCpu\">0</span>\n      </div>\n      <div class=\"meta\">\n        <span>Score call <b id=\"call\">0 – 0</b></span>\n        <span>Rally <b id=\"rally\">0</b></span>\n        <span>Longest <b id=\"best\">0</b></span>\n        <span id=\"netMeta\" hidden>Room <b id=\"roomCode\"></b> · Ping <b id=\"ping\">–</b></span>\n      </div>\n    </section>\n\n    <div class=\"court-box\" id=\"courtBox\">\n      <canvas id=\"cv\" role=\"img\" aria-label=\"Top-down pickleball court. You are at the bottom, the CPU at the top.\"></canvas>\n      <div class=\"banner\" id=\"banner\" aria-live=\"polite\" hidden><div class=\"b-title\" id=\"bTitle\"></div><div class=\"b-sub\" id=\"bSub\"></div></div>\n      <div class=\"hint\" id=\"hint\" hidden></div>\n      <div class=\"veil\" id=\"veil\" hidden><div class=\"b-title\">Paused</div><div class=\"b-sub\">Tap here or press P to resume</div></div>\n      <div class=\"pill\" id=\"pill\" aria-label=\"Score\"><i class=\"sw you\"></i><i class=\"sv\" id=\"pvYou\"></i><b id=\"pYou\">0</b><span class=\"sep\"></span><b id=\"pCpu\">0</b><i class=\"sv\" id=\"pvCpu\"></i><i class=\"sw cpu\"></i></div>\n      <button type=\"button\" class=\"pause\" id=\"btnPause\" aria-label=\"Pause\" aria-pressed=\"false\"><i></i><i></i></button>\n      <div class=\"lobby\" id=\"lobby\" role=\"dialog\" aria-labelledby=\"lobTitle\" hidden>\n        <div class=\"lob-card\">\n          <div class=\"lob-head\"><div class=\"b-title\" id=\"lobTitle\">Play online</div><button type=\"button\" class=\"lob-x\" id=\"lobClose\" aria-label=\"Close\">&times;</button></div>\n          <div class=\"lob-sec\" id=\"lobMenu\">\n            <label class=\"lob-lbl\" for=\"lobName\">Your name</label>\n            <input class=\"lob-in\" id=\"lobName\" maxlength=\"16\" autocomplete=\"nickname\" placeholder=\"Player\">\n            <button type=\"button\" class=\"lob-btn primary\" id=\"lobCreate\">Create game</button>\n            <div class=\"lob-or\">or join a friend</div>\n            <form class=\"lob-join\" id=\"lobJoin\">\n              <label class=\"sr-only\" for=\"lobCode\">Room code</label>\n              <input class=\"lob-in code\" id=\"lobCode\" maxlength=\"4\" placeholder=\"CODE\" autocapitalize=\"characters\" autocomplete=\"off\" spellcheck=\"false\" inputmode=\"text\">\n              <button type=\"submit\" class=\"lob-btn\" id=\"lobJoinBtn\">Join</button>\n            </form>\n            <p class=\"lob-err\" id=\"lobErr\" role=\"alert\"></p>\n          </div>\n          <div class=\"lob-sec\" id=\"lobWait\" hidden>\n            <p class=\"lob-p\">Share this code with your opponent</p>\n            <div class=\"lob-code\" id=\"lobRoom\" aria-live=\"polite\"></div>\n            <button type=\"button\" class=\"lob-btn\" id=\"lobCopy\">Copy invite link</button>\n            <p class=\"lob-p\" id=\"lobStatus\"><span class=\"dot\" aria-hidden=\"true\"></span>Waiting for an opponent to join</p>\n            <button type=\"button\" class=\"lob-link\" id=\"lobCancel\">Cancel</button>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"pad\" id=\"padBox\" aria-label=\"Swing controls\">\n      <div class=\"stick-hint\" id=\"stickHint\" aria-hidden=\"true\"><span>Move</span></div>\n      <div class=\"stick\" id=\"stick\" aria-hidden=\"true\"><div class=\"knob\" id=\"knob\"></div></div>\n      <button type=\"button\" class=\"btn primary\" id=\"btnDrive\"><span class=\"b-t\">Drive</span><span class=\"b-s d\">Hold Click · Space</span><span class=\"b-s m\">Hold: power</span></button>\n      <button type=\"button\" class=\"btn\" id=\"btnDink\"><span class=\"b-t\">Dink</span><span class=\"b-s d\">Hold Right-click · X</span><span class=\"b-s m\">Hold: touch</span></button>\n    </div>\n\n    <section class=\"panel info\" aria-label=\"Rules and controls\">\n      <h2>Rules on this court</h2>\n      <ul>\n        <li><b>Two bounces.</b> The serve and the return each have to bounce before anyone volleys.</li>\n        <li><b>The kitchen.</b> The 7-foot zone on each side of the net. Volley from inside it and you lose the point. A dink that lands in it is legal and awkward to return.</li>\n        <li><b>Side-out scoring.</b> Only the server scores. Lose a rally as server and the serve passes over.</li>\n        <li><b>Serving.</b> An even score serves from the right court, odd from the left, always to the diagonal box beyond the kitchen.</li>\n        <li><b>Power meter.</b> Hold Drive or Dink and a ring fills around your player. Release in the yellow band for a fast, accurate shot. Hold into the red and the shot sails long. A quick tap hits a normal shot.</li>\n        <li><b>Online.</b> Press Play online and create a game to get a four-letter room code, then send it or the invite link to a friend. You both see yourselves at the bottom of the court. Pausing pauses the game for both of you.</li>\n        <li><b>Spin.</b> Release, then brush sideways while you swing. Sweep left and the ball heads right, sweep right and it heads left. It lands that way of your aim, then kicks further that way off the bounce. Overdo it and it goes wide. A spun ball is harder to read and harder to return.</li>\n      </ul>\n      <h2>Controls</h2>\n      <dl class=\"ctl\">\n        <dt>Move</dt><dd>Mouse, finger drag, or <kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> / arrows</dd>\n        <dt>Drive</dt><dd>Hold click, <kbd>Space</kbd> or <kbd>Z</kbd> to charge, release to hit</dd>\n        <dt>Dink</dt><dd>Hold right-click or <kbd>X</kbd> to charge, release to hit</dd>\n        <dt>Aim</dt><dd>Meet the ball with the left or right side of your paddle. The dashed ring is your reach and brightens when the ball is in range.</dd>\n        <dt>Spin</dt><dd>Release a shot, then brush sideways right away with <kbd>A</kbd> or <kbd>D</kbd>, a drag, or a quick mouse swipe. Brush left and the ball goes right. Brush right and it goes left. Auto swing never adds spin.</dd>\n        <dt>Touch</dt><dd>On a phone, touch the left side of the court and a stick appears under your thumb: push to move, further for faster. Hold Drive or Dink to charge and release to swing, or just tap for a normal shot. Auto swing hits a decent shot for you when the ball is in reach. Hold a button to take over.</dd>\n      </dl>\n    </section>\n  </div>\n</main>\n\n<script>\n(function(){\n'use strict';\n\n/* ---------- helpers ---------- */\nconst $=id=>document.getElementById(id);\nconst clamp=(v,a,b)=>v<a?a:v>b?b:v;\nconst rnd=(a,b)=>a+Math.random()*(b-a);\nconst lerp=(a,b,t)=>a+(b-a)*t;\nconst mqTouch=window.matchMedia('(max-width:879px),(pointer:coarse)');\nconst touchUI=()=>mqTouch.matches;\nconst other=w=>w==='you'?'cpu':'you';\nconst NAME={you:'You',cpu:'CPU'};\nconst CFG=/*KL_CONFIG*/null||{};\n// Online play. Every client runs the game as 'you' at the bottom. Messages are mirrored on the way in.\n// Each player decides their own hits and anything that happens on their own half of the court.\nconst MP={on:false,role:'',pending:'',ch:null,room:'',id:Math.random().toString(36).slice(2,10),\n  peers:[],synced:false,tracked:false,rtt:.08,posT:0,pingT:0,swn:0,name:'Player'};\n\n/* ---------- court, in feet ---------- */\nconst CW=20, CL=44, NET=22, KIT=7, NET_H=2.95;\nconst G=30, REACH=3.3, SW=.26, KICK=3.2, SPIN_D=2.2;\nconst V={x0:-3.2,y0:-5.2,x1:23.2,y1:49.2}, VW=V.x1-V.x0, VH=V.y1-V.y0;\nconst DIFF={\n  easy:  {speed:11.5,err:2.6,miss:.12, dink:.30,spin:0},\n  medium:{speed:15.5,err:1.6,miss:.06, dink:.45,spin:.12},\n  hard:  {speed:19.5,err:.9, miss:.025,dink:.60,spin:.28}\n};\nconst HOLES=[[0,0],[.5,.2],[-.5,.25],[.1,-.55],[-.2,.62],[.55,-.35],[-.55,-.3]];\n\n/* ---------- state ---------- */\nconst P={\n  you:{x:15,y:45.4,tx:15,ty:45.4,swing:0,cool:0,kind:'drive',hit:false,lx:15,vxs:0,peak:0,spinOK:false,qual:'',pw:.5,f:0},\n  cpu:{x:5,y:-1.4,gx:5,gy:-1.4,swing:0,cool:0,kind:'drive',hit:false,think:0,bx:0,by:0}\n};\n// sp: spin, -1..1 (positive curves toward +x). ax: sideways curve acceleration until the first bounce.\n// vis and rot drive the spinning ball graphic.\nconst ball={x:15,y:44.6,z:2.6,vx:0,vy:0,vz:0,hitter:null,bounces:0,trail:[],sp:0,ax:0,vis:0,rot:0};\nconst S={mode:'ready',server:'you',score:{you:0,cpu:0},hits:0,diff:'medium',readyT:0,deadT:0,\n  gameOver:false,hintT:0,aimX:5,best:0,fx:[],sound:true,auto:touchUI(),paused:false};\nconst keys={left:0,right:0,up:0,down:0};\n\n/* ---------- power meter ---------- */\n// f is the charge fraction 0..1. Power runs from .45 (a plain tap) up to 1.\n// Sweet band: fast and accurate. Past OVER0 the shot gets pushed long.\nconst CHARGE_T=1.1, SWEET0=.35, SWEET1=.8, OVER0=.88;\nconst charge={active:false,kind:'drive',t:0,src:''};\nconst powerOf=f=>.45+.55*f;\nconst fOf=()=>clamp(charge.t/CHARGE_T,0,1);\nconst overOf=f=>Math.max(0,(f-OVER0)/(1-OVER0));\n// Spin comes from how fast you brush sideways while the swing is live (ft/s, signed).\n// A brush pushes the ball the other way: sweep left and it goes right.\nconst spinFrom=v=>{const a=Math.abs(v);return a<7?0:-Math.sign(v)*clamp((a-7)/13,0,1)};\n\nfunction loadBest(){try{return +localStorage.getItem('kl-best')||0}catch(e){return 0}}\nfunction saveBest(v){try{localStorage.setItem('kl-best',String(v))}catch(e){}}\nS.best=loadBest();\n\n/* ---------- audio ---------- */\nlet AC=null;\nfunction unlockAudio(){\n  if(AC===null){try{AC=new (window.AudioContext||window.webkitAudioContext)()}catch(e){AC=false}}\n  if(AC&&AC.state==='suspended'){try{AC.resume()}catch(e){}}\n}\nfunction pock(freq,len,vol){\n  if(!S.sound||!AC)return;\n  try{\n    const t=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();\n    o.type='triangle';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(freq*.45,t+len);\n    g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+len);\n    o.connect(g);g.connect(AC.destination);o.start(t);o.stop(t+len+.02);\n  }catch(e){}\n}\nconst tick=()=>pock(320,.05,.07);\n\n/* ---------- serving geometry ---------- */\nfunction serveSpot(who){\n  const even=S.score[who]%2===0;\n  return who==='you'?{x:even?15:5,y:45.4}:{x:even?5:15,y:-1.4};\n}\nfunction serviceBox(){\n  const even=S.score[S.server]%2===0;\n  if(S.server==='you')return even?{x0:0,x1:10,y0:0,y1:NET-KIT}:{x0:10,x1:20,y0:0,y1:NET-KIT};\n  return even?{x0:10,x1:20,y0:NET+KIT,y1:CL}:{x0:0,x1:10,y0:NET+KIT,y1:CL};\n}\nfunction inService(x,y){const b=serviceBox();return x>=b.x0&&x<=b.x1&&y>=b.y0&&y<=b.y1}\n\n/* ---------- ball physics ---------- */\nfunction phys(b,dt){\n  if(b.sp)b.vx+=b.ax*dt;\n  b.x+=b.vx*dt;b.y+=b.vy*dt;b.vz-=G*dt;b.z+=b.vz*dt;\n  let bounced=false;\n  if(b.z<=0){\n    b.z=0;\n    if(b.vz<-1.5){\n      bounced=true;b.vz=-b.vz*.74;b.vx*=.9;b.vy*=.9;\n      if(b.sp){b.vx+=b.sp*KICK;b.sp=0;b.ax=0} // spin kicks the ball sideways off the bounce\n    }\n    else{b.vz=0;const f=1-2.5*dt;b.vx*=f;b.vy*=f}\n  }\n  return bounced;\n}\n// Launch from the ball's current position so it lands at (tx,ty), clearing the net.\nfunction launch(tx,ty,speed){\n  const dx=tx-ball.x,dy=ty-ball.y,dist=Math.hypot(dx,dy);\n  let T=Math.max(.45,dist/speed),vx=0,vy=0,vz=0;\n  for(let i=0;i<60&&T<3.2;i++){\n    vx=dx/T;vy=dy/T;vz=(.5*G*T*T-ball.z)/T;\n    if(Math.abs(dy)<.001)break;\n    const tn=(NET-ball.y)/vy;\n    if(tn<=0||tn>=T)break;\n    const zn=ball.z+vz*tn-.5*G*tn*tn;\n    if(zn>NET_H+.55)break;\n    T+=.05;\n  }\n  ball.vx=vx;ball.vy=vy;ball.vz=vz;\n  return T;\n}\nfunction strike(who,tx,ty,speed,spin=0){\n  ball.z=Math.max(ball.z,.9);\n  if(who==='cpu'&&spin)tx-=spin*SPIN_D; // the CPU aims off so its spin lands where it meant\n  const T=launch(tx,ty,speed);\n  // Spin drifts the ball toward its side: it leaves on the aim line, curves, and lands SPIN_D feet over.\n  if(spin){ball.ax=2*spin*SPIN_D/(T*T);ball.sp=spin}\n  else{ball.sp=0;ball.ax=0}\n  ball.vis=spin;ball.tx=tx;ball.T0=T;\n  ball.hitter=who;ball.bounces=0;S.hits++;\n  $('rally').textContent=S.hits;\n  S.fx.push({x:ball.x,y:ball.y-ball.z*.55,t:0});\n  pock(who==='you'?920:780,.07,.2);\n  if(who==='you'&&MP.on)netSend({t:'hit',b:packBall(),h:S.hits,n:P.you.swn|0});\n  if(who==='you'){\n    const d=DIFF[S.diff];\n    const m=1+Math.abs(spin)*1.2; // spin is harder to read\n    P.cpu.bx=(Math.random()-.5)*d.err*1.3*m;P.cpu.by=(Math.random()-.5)*d.err*1.3*m;P.cpu.think=0;\n  }\n}\n\n// Re-solve the sideways path mid-flight for a new spin: head straight at the aim point (ball.tx),\n// then drift toward the spin side. Used when the player keeps moving sideways after contact.\nfunction reSpin(s2){\n  const vz=ball.vz,z=Math.max(ball.z,0);\n  const Tr=(vz+Math.sqrt(vz*vz+2*G*z))/G;\n  if(Tr<.1)return;\n  const D=s2*SPIN_D*Math.min(1,Tr/ball.T0);\n  ball.vx=(ball.tx-ball.x)/Tr;\n  ball.ax=2*D/(Tr*Tr);ball.sp=s2;ball.vis=s2;\n}\n\n/* ---------- shots ---------- */\nfunction youShot(kind){\n  const b=ball,p=P.you;\n  const dist=Math.hypot(b.x-p.x,b.y-p.y);\n  const off=clamp(b.x-p.x,-REACH,REACH);\n  const pw=p.pw,f=p.f,over=overOf(f);\n  const sweet=f>=SWEET0&&f<=SWEET1;\n  const sloppy=(.35+dist*.45)*(sweet?.55:1)+over*1.2;\n  const base=clamp(10+off*4.4+(10-b.x)*.5,1.2,18.8);\n  const tx=base+(Math.random()-.5)*sloppy*2;\n  const extra=over*rnd(.4,4.2); // overcharged shots are pushed past the baseline\n  const spin=p.spinOK?spinFrom(p.peak):0;\n  if(kind==='drive')return{tx,ty:lerp(9.5,1.0,pw)-extra+(Math.random()-.5)*sloppy*1.6,speed:lerp(26,42,pw),spin};\n  return{tx,ty:lerp(20.8,14.0,pw)-extra*.6+(Math.random()-.5)*sloppy*1.2,speed:lerp(12,18.5,pw),spin};\n}\nfunction cpuShot(kind){\n  const d=DIFF[S.diff],p=P.cpu;\n  const dist=Math.hypot(ball.x-p.x,ball.y-p.y),e=d.err;\n  if(Math.random()<d.miss){ // unforced error\n    const r=Math.random();\n    return r<.4?{tx:-1.6,ty:rnd(30,40),speed:30}:r<.8?{tx:21.6,ty:rnd(30,40),speed:30}:{tx:rnd(4,16),ty:46,speed:33};\n  }\n  const awayX=P.you.x<10?rnd(11,18):rnd(2,9);\n  const cs=()=>Math.random()<d.spin?(Math.random()<.5?-1:1)*rnd(.4,.9):0;\n  if(dist>REACH-.8)return{tx:rnd(6,14),ty:rnd(31,36),speed:rnd(17,20)}; // stretched, so a pop-up\n  if(kind==='dink')return{tx:clamp(awayX,2.5,17.5)+(Math.random()-.5)*e,ty:rnd(23.3,27.6)+(Math.random()-.5)*e*.8,speed:rnd(13,16),spin:cs()};\n  return{tx:awayX+(Math.random()-.5)*e*1.6,ty:rnd(35,41.2)+(Math.random()-.5)*e*1.4,speed:rnd(31,37),spin:cs()};\n}\nfunction cpuKind(){\n  return(ball.y>11.5&&ball.z<2.6&&Math.random()<DIFF[S.diff].dink)?'dink':'drive';\n}\n\n/* ---------- hitting and rules ---------- */\nfunction startSwing(who,kind){\n  const p=P[who];\n  if(p.swing>0||p.cool>0)return false;\n  p.swing=SW;p.kind=kind;p.hit=false;p.peak=0;\n  if(who==='you')p.swn=(p.swn|0)+1;\n  return true;\n}\nfunction tryHit(who){\n  const p=P[who],b=ball;\n  if(b.hitter===who)return false;\n  if(who==='you'?b.y<NET+.1:b.y>NET-.1)return false;\n  if(Math.hypot(b.x-p.x,b.y-p.y)>REACH||b.z>5.4)return false;\n  if(b.bounces===0){\n    if(S.hits<3){ // two-bounce rule\n      if(who==='you')showHint('Let it bounce first. The serve and the return both have to bounce.',1.6);\n      return false;\n    }\n    const inK=who==='you'?p.y<NET+KIT-.4:p.y>NET-KIT+.4;\n    if(inK){endPoint(other(who),'kitchen');return true}\n  }\n  const s=who==='you'?youShot(p.kind):cpuShot(p.kind);\n  strike(who,s.tx,s.ty,s.speed,s.spin||0);\n  if(who==='you'){\n    const sp=s.spin||0,dir=sp>.12?'Curve right':sp<-.12?'Curve left':'';\n    const txt=[p.qual,dir].filter(Boolean).join(' · ');\n    if(txt)showHint(txt,.9);\n  }\n  return true;\n}\nfunction onBounce(){\n  ball.bounces++;\n  const b=ball,h=b.hitter;\n  if(MP.on&&b.y<=NET){if(b.bounces===1)tick();return} // the opponent calls bounces on their half\n  if(b.bounces===1){\n    const inX=b.x>=0&&b.x<=CW,inY=b.y>=0&&b.y<=CL;\n    if(!inX||!inY){endPoint(other(h),!inY?'long':'wide');return}\n    if(h==='you'?b.y>=NET:b.y<=NET){endPoint(other(h),'short');return}\n    if(S.hits===1&&!inService(b.x,b.y)){endPoint(other(h),'service');return}\n    tick();\n  }else{\n    endPoint(h,S.hits===1?'ace':'winner');\n  }\n}\nfunction stepBall(h){\n  if(S.mode==='ready')return;\n  const py=ball.y;\n  const bo=phys(ball,h);\n  if(S.mode==='rally'){\n    if((py-NET)*(ball.y-NET)<0&&ball.z<NET_H){\n      ball.y=py;ball.vy*=-.12;ball.vx*=.3;\n      if(!MP.on||ball.hitter==='you')endPoint(other(ball.hitter),'net');\n      return;\n    }\n    if(bo)onBounce();\n  }\n}\n\n/* ---------- points and games ---------- */\nfunction endPoint(winner,why,remote){\n  if(S.mode!=='rally')return;\n  if(MP.on&&!remote)queueMicrotask(()=>netSend({t:'pt',w:winner==='you'?'me':'them',why,\n    sc:[S.score.you,S.score.cpu],sv:S.server==='you'?'me':'them'}));\n  S.mode='dead';S.deadT=0;\n  const srv=S.server,L=other(winner),rally=S.hits;\n  if(rally>S.best){S.best=rally;saveBest(rally)}\n  if(winner===srv)S.score[srv]++;else S.server=winner;\n  const a=S.score.you,c=S.score.cpu;\n  S.gameOver=Math.max(a,c)>=11&&Math.abs(a-c)>=2;\n  const T={\n    ace:['Ace','Untouched serve'],\n    winner:[winner==='you'?'Winner':'Past you',winner==='you'?NAME.cpu+' could not return it':'You could not return it'],\n    long:['Out, long',NAME[L]+' hit it long'],\n    wide:['Out, wide',NAME[L]+' hit it wide'],\n    short:['Short',NAME[L]+' landed it on '+(L==='you'?'your':MP.on?'their':'its')+' own side'],\n    net:['Net',NAME[L]+' hit the net'],\n    kitchen:['Kitchen fault',NAME[L]+' volleyed in the kitchen'],\n    service:['Service fault',NAME[L]+' missed the service box']\n  }[why];\n  const result=winner===srv?'Point to '+NAME[winner]:'Side out, '+NAME[winner]+' to serve';\n  syncUI();\n  setBanner(T[0],T[1]+'. '+result+'.');\n}\nfunction setupPoint(){\n  S.mode='ready';S.readyT=0;S.hits=0;\n  const srv=S.server,rec=other(srv),sp=serveSpot(srv),box=serviceBox();\n  const rx=(box.x0+box.x1)/2,ry=rec==='you'?41.5:2.5;\n  const place=(w,x,y)=>{P[w].x=x;P[w].y=y;if(w==='you'){P.you.tx=x;P.you.ty=y}else{P.cpu.gx=x;P.cpu.gy=y}};\n  place(srv,sp.x,sp.y);place(rec,rx,ry);\n  P.you.lx=P.you.x;P.you.vxs=0;P.you.peak=0;\n  ball.hitter=null;ball.bounces=0;ball.vx=ball.vy=ball.vz=0;ball.trail.length=0;\n  ball.sp=0;ball.ax=0;ball.vis=0;\n  ball.x=sp.x;ball.y=sp.y+(srv==='you'?-.8:.8);ball.z=2.6;\n  S.aimX=(box.x0+box.x1)/2;\n  $('rally').textContent='0';\n  syncUI();\n  const call=S.score[srv]+' – '+S.score[rec];\n  if(srv==='you')setBanner('Your serve',touchUI()\n    ?'Score call '+call+'. Drag to aim. Hold Drive or Dink, release in the yellow.'\n    :'Score call '+call+'. Aim with the mouse or A / D, then hold Drive for a deep serve or Dink for a short one. Release in the yellow.');\n  else setBanner(NAME.cpu+' serves','Score call '+call+'. Let the serve bounce, then return it.');\n}\nfunction newGame(){\n  S.score.you=0;S.score.cpu=0;S.server=MP.on&&MP.role==='guest'?'cpu':'you';S.gameOver=false;\n  setupPoint();\n}\nfunction doServe(who,kind,f=0){\n  const sp=serveSpot(who),box=serviceBox(),d=DIFF[S.diff];\n  ball.x=sp.x;ball.y=sp.y+(who==='you'?-.8:.8);ball.z=2.6;ball.vx=ball.vy=ball.vz=0;\n  P[who].swing=SW;P[who].hit=true;P[who].kind=kind;\n  if(who==='you')P.you.swn=(P.you.swn|0)+1;\n  let tx,ty,speed;\n  if(who==='you'){\n    const pw=powerOf(f),over=overOf(f),extra=over*rnd(.4,4.2);\n    tx=clamp(S.aimX,box.x0+1.4,box.x1-1.4)+(Math.random()-.5)*over*3;\n    ty=(kind==='drive'?lerp(9.5,1.2,pw):lerp(14.2,8.8,pw))-extra+rnd(-.5,.5);\n    speed=kind==='drive'?lerp(28,40,pw):lerp(22,32,pw);\n  }else{\n    const e=d.err*.55;\n    tx=rnd(box.x0+1.5,box.x1-1.5)+(Math.random()-.5)*e*2;\n    ty=(Math.random()<.55?rnd(38,42):rnd(31.8,35))+(Math.random()-.5)*e*2;\n    speed=rnd(30,36);\n  }\n  S.mode='rally';setBanner(null);\n  strike(who,tx,ty,speed);\n}\nfunction setMeterUI(f){\n  const on=k=>charge.active&&charge.kind===k?f:0;\n  $('btnDrive').style.setProperty('--c',on('drive'));\n  $('btnDink').style.setProperty('--c',on('dink'));\n}\nfunction cancelCharge(){charge.active=false;charge.t=0;setMeterUI(0)}\nfunction beginCharge(kind,src){\n  unlockAudio();\n  if(S.paused||S.lobby||charge.active)return;\n  if(S.mode==='over'){requestNewGame();return}\n  const ok=(S.mode==='ready'&&S.server==='you')||(S.mode==='rally'&&P.you.swing<=0&&P.you.cool<=0);\n  if(!ok)return;\n  charge.active=true;charge.kind=kind;charge.t=0;charge.src=src;\n}\nfunction endCharge(src){\n  if(!charge.active||charge.src!==src)return;\n  const kind=charge.kind,f=fOf(),held=charge.t;\n  cancelCharge();\n  const label=held>=.18?(f>=OVER0?'Overcooked':f>=SWEET0&&f<=SWEET1?'Sweet spot':f<SWEET0?'Light':'Strong'):'';\n  if(S.mode==='ready'&&S.server==='you'){\n    if(label)showHint(label,.9);\n    doServe('you',kind,f);\n  }else if(S.mode==='rally'){\n    P.you.pw=powerOf(f);P.you.f=f;P.you.spinOK=true;P.you.qual=label;\n    startSwing('you',kind);\n  }\n}\n// A tap is a charge of zero: a normal shot.\nfunction swingYou(kind){beginCharge(kind,'tap');endCharge('tap')}\n\n/* ---------- CPU ---------- */\nfunction predictHit(){\n  const b={x:ball.x,y:ball.y,z:ball.z,vx:ball.vx,vy:ball.vy,vz:ball.vz,sp:ball.sp,ax:ball.ax};\n  let bounces=ball.bounces,t=0;\n  for(let i=0;i<150;i++){\n    if(phys(b,1/60))bounces++;\n    t+=1/60;\n    if(b.y<NET-.4){\n      const volleyOK=S.hits>=3&&b.y<NET-KIT-.4;\n      if((bounces>=1&&b.z>.5&&b.z<3.2)||(volleyOK&&bounces===0&&b.z>.8&&b.z<4.2))return{x:b.x,y:b.y,t};\n    }\n    if(bounces>=2)break;\n  }\n  return null;\n}\nfunction planCpu(){\n  const c=P.cpu;\n  if(ball.hitter==='you'){\n    const h=predictHit();\n    if(h){c.gx=clamp(h.x+c.bx,-1.6,21.6);c.gy=clamp(h.y+c.by,-3.4,NET-.9)}\n    else{c.gx=clamp(ball.x,-1.6,21.6)}\n  }else{\n    c.gx=10+(ball.x-10)*.3;c.gy=9.5;\n  }\n}\nfunction cpuUpdate(dt){\n  const c=P.cpu,d=DIFF[S.diff];\n  if(S.mode==='rally'){\n    c.think-=dt;\n    if(c.think<=0){c.think=.12;planCpu()}\n  }\n  const dx=c.gx-c.x,dy=c.gy-c.y,dist=Math.hypot(dx,dy);\n  if(dist>.001){const st=Math.min(dist,d.speed*dt);c.x+=dx/dist*st;c.y+=dy/dist*st}\n  c.x=clamp(c.x,-2,22);c.y=clamp(c.y,-3.6,NET-.7);\n  if(S.mode==='rally'&&ball.hitter==='you'&&c.swing<=0&&c.cool<=0){\n    const near=Math.hypot(ball.x-c.x,ball.y-c.y)<REACH-.35&&ball.z<5&&ball.y<NET-.1;\n    const okVolley=ball.bounces>0||(S.hits>=3&&c.y<NET-KIT-.4);\n    if(near&&okVolley)startSwing('cpu',cpuKind());\n  }\n}\n\n/* ---------- player movement ---------- */\nconst stickV={x:0,y:0};\nfunction moveYou(dt){\n  const p=P.you,sp=((stickV.x||stickV.y)&&!MP.on)?24:17;\n  if(S.mode==='ready'&&S.server==='you'){\n    S.aimX=clamp(S.aimX+clamp(keys.right-keys.left+stickV.x,-1,1)*14*dt,-2,22);return;\n  }\n  const kx=keys.right-keys.left+stickV.x,ky=keys.down-keys.up+stickV.y;\n  if(kx||ky){\n    const m=Math.max(1,Math.hypot(kx,ky));p.x+=kx/m*sp*dt;p.y+=ky/m*sp*dt;\n    p.x=clamp(p.x,-2,22);p.y=clamp(p.y,NET+.7,CL+3.6);p.tx=p.x;p.ty=p.y;\n  }else{\n    const dx=p.tx-p.x,dy=p.ty-p.y,d=Math.hypot(dx,dy);\n    if(d>.001){const st=Math.min(d,sp*1.25*dt);p.x+=dx/d*st;p.y+=dy/d*st}\n  }\n}\n\n/* ---------- main update ---------- */\nfunction update(dt){\n  if(charge.active){\n    if((S.mode==='ready'&&S.server==='you')||S.mode==='rally'){charge.t+=dt;setMeterUI(fOf())}\n    else cancelCharge();\n  }\n  for(const w of['you','cpu']){\n    const p=P[w];\n    if(p.swing>0){p.swing-=dt;if(p.swing<=0){p.swing=0;p.cool=.12;p.qual=''}}\n    else if(p.cool>0)p.cool-=dt;\n  }\n  if(S.hintT>0){S.hintT-=dt;if(S.hintT<=0)$('hint').hidden=true}\n  for(let i=S.fx.length-1;i>=0;i--){S.fx[i].t+=dt;if(S.fx[i].t>.3)S.fx.splice(i,1)}\n  moveYou(dt);\n  { // sideways speed, smoothed. The fastest value during a live swing becomes the spin.\n    const y=P.you,vi=dt>0?(y.x-y.lx)/dt:0;\n    y.lx=y.x;y.vxs+=(vi-y.vxs)*Math.min(1,dt*20);\n    if(y.swing>0&&Math.abs(y.vxs)>Math.abs(y.peak))y.peak=y.vxs;\n  }\n  if(MP.on)netUpdate(dt);else cpuUpdate(dt);\n\n  if(S.mode==='ready'){\n    const sp=serveSpot(S.server);\n    ball.x=sp.x;ball.y=sp.y+(S.server==='you'?-.8:.8);ball.z=2.6;\n    if(S.server==='cpu'&&!MP.on){S.readyT+=dt;if(S.readyT>1.2)doServe('cpu',cpuKind())}\n  }else if(S.mode==='rally'||S.mode==='dead'){\n    const n=Math.max(1,Math.ceil(dt/(1/120))),h=dt/n;\n    for(let i=0;i<n;i++)stepBall(h);\n    if(S.mode==='rally'){\n      if(S.auto&&!charge.active&&ball.hitter==='cpu'&&P.you.swing<=0&&P.you.cool<=0&&ball.y>NET+.1&&ball.z<5&&\n         Math.hypot(ball.x-P.you.x,ball.y-P.you.y)<REACH-.4&&\n         (ball.bounces>0||(S.hits>=3&&P.you.y>=NET+KIT-.4))){\n        P.you.f=.45;P.you.pw=powerOf(.45);P.you.spinOK=false;P.you.qual='';\n        startSwing('you',ball.y<NET+12&&ball.z<2.5?'dink':'drive');\n      }\n      for(const w of['you','cpu']){\n        if(MP.on&&w==='cpu')continue; // the opponent's client decides their hits\n        const p=P[w];\n        if(p.swing>0&&!p.hit&&S.mode==='rally'&&tryHit(w))p.hit=true;\n      }\n      // Moving sideways after contact still adds spin until the swing ends.\n      if(S.mode==='rally'&&P.you.hit&&P.you.swing>0&&P.you.spinOK&&ball.hitter==='you'&&ball.bounces===0){\n        const s2=spinFrom(P.you.peak);\n        if(Math.abs(s2)>Math.abs(ball.sp)+.03){\n          const m=(1+Math.abs(s2)*1.2)/(1+Math.abs(ball.sp)*1.2);\n          P.cpu.bx*=m;P.cpu.by*=m;\n          reSpin(s2);\n          if(MP.on)netSend({t:'spin',b:packBall()});\n          showHint([P.you.qual,s2>0?'Curve right':'Curve left'].filter(Boolean).join(' · '),.9);\n        }\n      }\n      if(S.mode==='rally'&&P.you.y<NET+KIT-.4&&S.hits>=3&&ball.hitter==='cpu'&&ball.bounces===0&&ball.y>NET){\n        showHint('You are in the kitchen. Let it bounce or step back.',.25);\n      }\n    }\n    ball.trail.push({x:ball.x,y:ball.y,z:ball.z});\n    ball.rot+=ball.vis*22*dt;\n    while(ball.trail.length>9+Math.round(Math.abs(ball.vis)*14))ball.trail.shift(); // spun balls leave a longer trail\n    if(S.mode==='dead'){\n      S.deadT+=dt;\n      if(S.deadT>1.8){\n        if(S.gameOver){\n          S.mode='over';\n          const a=S.score.you,c=S.score.cpu;\n          setBanner(a>c?'You win':NAME.cpu+' wins',Math.max(a,c)+' to '+Math.min(a,c)+'. Click, tap or press Space to play again.');\n        }else setupPoint();\n      }\n    }\n  }\n}\n\n/* ---------- pause ---------- */\nfunction setPaused(p,remote){\n  if(p===S.paused)return;\n  S.paused=p;\n  if(MP.on&&!remote)netSend({t:'pause',p});\n  if(p){cancelCharge();keys.left=keys.right=keys.up=keys.down=0;touch.id=null;stickRelease()}\n  $('btnPause').setAttribute('aria-pressed',String(p));\n  $('btnPause').setAttribute('aria-label',p?'Resume':'Pause');\n  $('veil').hidden=!p;\n}\nconst togglePause=()=>setPaused(!S.paused);\n\n/* ---------- UI sync ---------- */\nfunction syncUI(){\n  $('sYou').textContent=S.score.you;$('sCpu').textContent=S.score.cpu;\n  $('nameCpu').textContent=NAME.cpu;\n  $('rowYou').dataset.serving=String(S.server==='you');\n  $('rowCpu').dataset.serving=String(S.server==='cpu');\n  $('call').textContent=S.score[S.server]+' – '+S.score[other(S.server)];\n  $('best').textContent=S.best;\n  $('pYou').textContent=S.score.you;$('pCpu').textContent=S.score.cpu;\n  $('pvYou').classList.toggle('on',S.server==='you');$('pvCpu').classList.toggle('on',S.server==='cpu');\n}\nfunction setBanner(t,s){\n  const el=$('banner');\n  if(!t){el.hidden=true;return}\n  $('bTitle').textContent=t;$('bSub').textContent=s||'';el.hidden=false;\n}\nfunction showHint(text,sec){\n  const el=$('hint');\n  if(el.textContent!==text)el.textContent=text;\n  el.hidden=false;S.hintT=sec;\n}\n\n/* ---------- drawing ---------- */\nconst cv=$('cv'),ctx=cv.getContext('2d');\nlet K=1,courtCv=null;\nfunction circle(c,x,y,r){c.beginPath();c.arc(x,y,r,0,Math.PI*2)}\nfunction ell(c,x,y,rx,ry){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2)}\nfunction rr(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath()}\nfunction ln(c,x1,y1,x2,y2){c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke()}\n\nfunction buildCourt(){\n  courtCv=document.createElement('canvas');courtCv.width=cv.width;courtCv.height=cv.height;\n  const c=courtCv.getContext('2d');\n  c.setTransform(K,0,0,K,-V.x0*K,-V.y0*K);\n  c.fillStyle='#2E6B58';c.fillRect(V.x0,V.y0,VW,VH);\n  let seed=7;const rr_=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};\n  c.fillStyle='rgba(255,255,255,.05)';\n  for(let i=0;i<500;i++)c.fillRect(V.x0+rr_()*VW,V.y0+rr_()*VH,.12,.12);\n  c.fillStyle='#2F6EB5';c.fillRect(0,0,CW,CL);\n  c.fillStyle='#255A99';c.fillRect(0,NET-KIT,CW,KIT*2);\n  c.fillStyle='rgba(255,255,255,.045)';\n  for(let i=0;i<700;i++)c.fillRect(rr_()*CW,rr_()*CL,.1,.1);\n  c.strokeStyle='#F4F7FA';c.lineWidth=.2;c.lineJoin='miter';\n  c.strokeRect(0,0,CW,CL);\n  ln(c,0,NET-KIT,CW,NET-KIT);ln(c,0,NET+KIT,CW,NET+KIT);\n  ln(c,CW/2,0,CW/2,NET-KIT);ln(c,CW/2,NET+KIT,CW/2,CL);\n  c.textAlign='center';c.textBaseline='middle';\n  if('letterSpacing' in c)c.letterSpacing='.22px';\n  c.fillStyle='rgba(244,247,250,.24)';\n  c.font='700 1.05px \"Hanken Grotesk\",sans-serif';\n  c.fillText('NON-VOLLEY ZONE',CW/2,NET+KIT/2);c.fillText('NON-VOLLEY ZONE',CW/2,NET-KIT/2);\n  c.fillStyle='rgba(255,255,255,.55)';c.font='700 .95px \"Hanken Grotesk\",sans-serif';\n  c.fillText('20 FT',CW/2,CL+2.3);\n  c.fillText('7 FT',CW+1.7,NET+KIT/2);c.fillText('7 FT',CW+1.7,NET-KIT/2);\n  c.save();c.translate(-1.9,CL/2);c.rotate(-Math.PI/2);c.fillText('44 FT',0,0);c.restore();\n}\n\nfunction drawPlayer(who){\n  const p=P[who],you=who==='you';\n  ctx.save();ctx.translate(p.x,p.y);ctx.rotate(you?0:Math.PI);\n  ctx.fillStyle='rgba(8,18,30,.28)';ell(ctx,.15,.25,1.25,.85);ctx.fill();\n  ctx.fillStyle=you?'#E8553A':'#EDF2F7';ctx.strokeStyle='rgba(8,18,30,.6)';ctx.lineWidth=.1;\n  ell(ctx,0,0,1.15,.7);ctx.fill();ctx.stroke();\n  ctx.fillStyle='#1C2833';circle(ctx,0,-.1,.5);ctx.fill();\n  let ang=.35;\n  if(p.swing>0){const u=1-p.swing/SW,e=1-Math.pow(1-u,2);ang=.9+(-1.0-.9)*e}\n  else if(you&&charge.active)ang=.55+.7*fOf(); // paddle winds back while charging\n  ctx.save();ctx.translate(1.0,-.3);ctx.rotate(ang);\n  ctx.fillStyle='#1C2833';rr(ctx,-.13,-.7,.26,.75,.1);ctx.fill();\n  ctx.fillStyle=you?'#FF7B5C':'#9FD3F0';ctx.strokeStyle=you?'#7A2312':'#1E4C6E';ctx.lineWidth=.12;\n  rr(ctx,-.55,-1.95,1.1,1.3,.42);ctx.fill();ctx.stroke();\n  ctx.restore();\n  ctx.restore();\n}\nfunction drawNet(){\n  ctx.fillStyle='rgba(6,16,26,.25)';ctx.fillRect(-1.2,NET+.1,22.4,.5);\n  ctx.fillStyle='rgba(9,20,31,.8)';ctx.fillRect(-1.2,NET-.2,22.4,.4);\n  ctx.strokeStyle='rgba(255,255,255,.3)';ctx.lineWidth=.04;\n  for(let x=-1.2;x<=21.2;x+=.5)ln(ctx,x,NET-.2,x,NET+.2);\n  ctx.fillStyle='#F4F7FA';ctx.fillRect(-1.2,NET-.2,22.4,.1);\n  ctx.fillStyle='#20262C';circle(ctx,-1.2,NET,.38);ctx.fill();circle(ctx,21.2,NET,.38);ctx.fill();\n  ctx.fillStyle='rgba(255,255,255,.35)';circle(ctx,-1.28,NET-.08,.12);ctx.fill();circle(ctx,21.12,NET-.08,.12);ctx.fill();\n}\nfunction drawBall(){\n  const b=ball,by=b.y-b.z*.55,r=.4+b.z*.02;\n  for(let i=0;i<b.trail.length;i++){\n    const t=b.trail[i],f=(i+1)/b.trail.length;\n    ctx.fillStyle='rgba(228,242,58,'+(f*(.28+Math.abs(b.vis)*.4)).toFixed(3)+')';\n    circle(ctx,t.x,t.y-t.z*.55,r*.55*f+.05);ctx.fill();\n  }\n  ctx.fillStyle='#E4F23A';ctx.strokeStyle='#8A9510';ctx.lineWidth=.07;\n  circle(ctx,b.x,by,r);ctx.fill();ctx.stroke();\n  ctx.fillStyle='rgba(110,120,10,.75)';\n  const ca=Math.cos(b.rot),sa=Math.sin(b.rot);\n  for(const h of HOLES){\n    const hx=h[0]*ca-h[1]*sa,hy=h[0]*sa+h[1]*ca;\n    circle(ctx,b.x+hx*r,by+hy*r,r*.17);ctx.fill();\n  }\n}\n\nfunction drawMeter(){\n  if(!charge.active)return;\n  const x=P.you.x,y=P.you.y,r=2.8,f=fOf(),A=-Math.PI/2,TAU=Math.PI*2;\n  const arc=(f0,f1,col,w)=>{ctx.strokeStyle=col;ctx.lineWidth=w;ctx.beginPath();ctx.arc(x,y,r,A+f0*TAU,A+f1*TAU);ctx.stroke()};\n  ctx.lineCap='butt';\n  arc(0,1,'rgba(8,18,30,.5)',.75);\n  arc(SWEET0,SWEET1,'rgba(228,242,58,.92)',.75);\n  arc(OVER0,1,'rgba(255,90,60,.95)',.75);\n  if(f>.005){ctx.lineCap='round';arc(0,f,'#FFFFFF',.26)}\n  const a=A+f*TAU;\n  ctx.fillStyle='#FFFFFF';ctx.strokeStyle='rgba(8,18,30,.7)';ctx.lineWidth=.1;\n  circle(ctx,x+Math.cos(a)*r,y+Math.sin(a)*r,.48);ctx.fill();ctx.stroke();\n  ctx.lineCap='butt';\n}\n\nfunction render(){\n  ctx.setTransform(1,0,0,1,0,0);\n  ctx.clearRect(0,0,cv.width,cv.height);\n  if(courtCv)ctx.drawImage(courtCv,0,0);\n  ctx.setTransform(K,0,0,K,-V.x0*K,-V.y0*K);\n\n  if(P.you.y<NET+KIT-.4&&S.mode!=='over'){\n    ctx.fillStyle='rgba(255,110,70,.2)';ctx.fillRect(0,NET,CW,KIT);\n  }\n  if(S.mode==='ready'){\n    const b=serviceBox();\n    ctx.fillStyle='rgba(228,242,58,.14)';ctx.fillRect(b.x0,b.y0,b.x1-b.x0,b.y1-b.y0);\n    ctx.strokeStyle='rgba(228,242,58,.75)';ctx.lineWidth=.12;ctx.setLineDash([.6,.5]);\n    ctx.strokeRect(b.x0+.1,b.y0+.1,b.x1-b.x0-.2,b.y1-b.y0-.2);ctx.setLineDash([]);\n    if(S.server==='you'){\n      const ax=clamp(S.aimX,b.x0+1.4,b.x1-1.4);\n      ctx.strokeStyle='rgba(255,255,255,.85)';ctx.lineWidth=.14;circle(ctx,ax,8.5,.8);ctx.stroke();\n      ctx.fillStyle='#fff';circle(ctx,ax,8.5,.16);ctx.fill();\n    }\n  }\n  if(S.mode==='rally'&&ball.hitter==='cpu'&&ball.bounces===0&&ball.vy>0){\n    const t=(ball.vz+Math.sqrt(ball.vz*ball.vz+2*G*ball.z))/G;\n    const lx=ball.x+ball.vx*t+(ball.sp?.5*ball.ax*t*t:0),ly=ball.y+ball.vy*t;\n    ctx.strokeStyle='rgba(255,255,255,.6)';ctx.lineWidth=.12;ctx.setLineDash([.35,.3]);\n    circle(ctx,lx,ly,.8);ctx.stroke();ctx.setLineDash([]);\n  }\n  // reach ring\n  const live=S.mode==='rally'&&ball.hitter==='cpu'&&ball.y>NET&&Math.hypot(ball.x-P.you.x,ball.y-P.you.y)<REACH&&ball.z<5.4;\n  ctx.strokeStyle=live?'rgba(255,255,255,.85)':'rgba(255,255,255,.22)';ctx.lineWidth=live?.14:.1;\n  ctx.setLineDash([.5,.4]);circle(ctx,P.you.x,P.you.y,REACH);ctx.stroke();ctx.setLineDash([]);\n\n  // ball shadow\n  ctx.fillStyle='rgba(6,16,26,'+Math.max(.12,.34-ball.z*.02).toFixed(3)+')';\n  ell(ctx,ball.x,ball.y+.05,.38,.26);ctx.fill();\n\n  drawPlayer('cpu');drawPlayer('you');\n  drawNet();\n  drawBall();\n  drawMeter();\n\n  for(const f of S.fx){\n    const k=f.t/.3;\n    ctx.strokeStyle='rgba(255,255,255,'+(1-k).toFixed(3)+')';ctx.lineWidth=.12;\n    circle(ctx,f.x,f.y,.6+k*2.6);ctx.stroke();\n  }\n}\n\n/* ---------- layout ---------- */\nfunction layout(){\n  const lay=$('layout');\n  const wide=window.matchMedia('(min-width:880px)').matches;\n  const availW=lay.clientWidth||360;\n  const maxW=wide?Math.min(availW*.5,560):availW;\n  const vh=window.innerHeight||800;\n  const maxH=Math.max(250,wide?vh-48:vh-lay.offsetTop-(deck()+2));\n  let cw=Math.min(maxW,maxH*VW/VH);\n  cw=Math.max(wide?240:160,Math.floor(cw));\n  const ch=Math.round(cw*VH/VW);\n  const dpr=Math.min(2,window.devicePixelRatio||1);\n  cv.style.width=cw+'px';cv.style.height=ch+'px';\n  cv.width=Math.round(cw*dpr);cv.height=Math.round(ch*dpr);\n  K=cv.width/VW;\n  buildCourt();\n}\n\n/* ---------- input ---------- */\nfunction toWorld(e){\n  const r=cv.getBoundingClientRect();\n  return{x:V.x0+(e.clientX-r.left)/r.width*VW,y:V.y0+(e.clientY-r.top)/r.height*VH};\n}\nfunction aim(e){\n  const w=toWorld(e);\n  S.aimX=w.x;\n  if(S.mode==='ready'&&S.server==='you')return;\n  P.you.tx=clamp(w.x,-2,22);P.you.ty=clamp(w.y,NET+.7,CL+3.6);\n}\n// Mouse: the player follows the cursor.\ncv.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')aim(e)});\ncv.addEventListener('pointerdown',e=>{\n  if(e.pointerType!=='mouse')return;\n  unlockAudio();aim(e);\n  if(S.mode==='over'){requestNewGame();return}\n  e.preventDefault();\n  try{cv.setPointerCapture(e.pointerId)}catch(_){}\n  if(e.button===2)beginCharge('dink','mouse');\n  else if(e.button===0)beginCharge(e.shiftKey?'dink':'drive','mouse');\n});\naddEventListener('pointerup',e=>{if(e.pointerType==='mouse')endCharge('mouse')});\naddEventListener('pointercancel',e=>{if(e.pointerType==='mouse')endCharge('mouse')});\ncv.addEventListener('contextmenu',e=>e.preventDefault());\n\n// Touch: drags are relative, so the player never jumps under the finger and stays visible.\n// Works on the court and on the scoreboard and button column, so the thumb can rest anywhere.\nconst touch={id:null,mode:'',sx:0,sy:0,px:0,py:0,ax:0};\nfunction touchAnchor(e){\n  touch.sx=e.clientX;touch.sy=e.clientY;touch.px=P.you.tx;touch.py=P.you.ty;touch.ax=S.aimX;\n  touch.mode=S.mode+S.server;\n}\nfunction touchDown(e){\n  if(S.paused||S.lobby||e.pointerType==='mouse'||e.target.closest('button')||stickOn())return;\n  unlockAudio();\n  if(S.mode==='over'){requestNewGame();return}\n  touch.id=e.pointerId;touchAnchor(e);\n  try{e.currentTarget.setPointerCapture(e.pointerId)}catch(_){}\n}\nfunction touchMove(e){\n  if(e.pointerId!==touch.id)return;\n  if(touch.mode!==S.mode+S.server)touchAnchor(e);\n  const k=2/(cv.getBoundingClientRect().width/VW);\n  const dx=(e.clientX-touch.sx)*k,dy=(e.clientY-touch.sy)*k;\n  if(S.mode==='ready'&&S.server==='you')S.aimX=clamp(touch.ax+dx*.6,-2,22);\n  else{P.you.tx=clamp(touch.px+dx,-2,22);P.you.ty=clamp(touch.py+dy,NET+.7,CL+3.6)}\n}\nfunction touchUp(e){if(e.pointerId===touch.id)touch.id=null}\n['cv','scoreBox','padBox'].forEach(id=>{\n  const el=$(id);\n  el.addEventListener('pointerdown',touchDown);\n  el.addEventListener('pointermove',touchMove);\n  el.addEventListener('pointerup',touchUp);\n  el.addEventListener('pointercancel',touchUp);\n});\n\naddEventListener('keydown',e=>{\n  const k=e.key;\n  const tag=e.target&&e.target.tagName;\n  if(tag==='INPUT'||tag==='TEXTAREA')return;\n  if(S.lobby){if(k==='Escape'&&!MP.pending)closeLobby();return}\n  if(k==='p'||k==='P'||k==='Escape'){if(!e.repeat)togglePause();e.preventDefault();return}\n  if(S.paused)return;\n  if((tag==='BUTTON'||tag==='SELECT'||tag==='INPUT')&&(k===' '||k==='Enter'))return;\n  unlockAudio();\n  if(k==='ArrowLeft'||k==='a'||k==='A'){keys.left=1;e.preventDefault()}\n  else if(k==='ArrowRight'||k==='d'||k==='D'){keys.right=1;e.preventDefault()}\n  else if(k==='ArrowUp'||k==='w'||k==='W'){keys.up=1;e.preventDefault()}\n  else if(k==='ArrowDown'||k==='s'||k==='S'){keys.down=1;e.preventDefault()}\n  else if(k===' '||k==='z'||k==='Z'){e.preventDefault();if(!e.repeat)beginCharge('drive','key')}\n  else if(k==='x'||k==='X'){if(!e.repeat)beginCharge('dink','key')}\n});\naddEventListener('keyup',e=>{\n  const k=e.key;\n  if(k==='ArrowLeft'||k==='a'||k==='A')keys.left=0;\n  else if(k==='ArrowRight'||k==='d'||k==='D')keys.right=0;\n  else if(k==='ArrowUp'||k==='w'||k==='W')keys.up=0;\n  else if(k==='ArrowDown'||k==='s'||k==='S')keys.down=0;\n  else if((k===' '||k==='z'||k==='Z')&&charge.kind==='drive')endCharge('key');\n  else if((k==='x'||k==='X')&&charge.kind==='dink')endCharge('key');\n});\naddEventListener('blur',()=>{keys.left=keys.right=keys.up=keys.down=0;cancelCharge();if(S.mode==='rally')setPaused(true)});\naddEventListener('visibilitychange',()=>{if(document.hidden&&S.mode!=='over')setPaused(true)});\n\nfunction bindSwing(id,kind){\n  const b=$(id);\n  b.addEventListener('pointerdown',e=>{\n    if(e.pointerType==='mouse'&&e.button!==0)return;\n    e.preventDefault();\n    try{b.setPointerCapture(e.pointerId)}catch(_){}\n    beginCharge(kind,'btn'+e.pointerId);\n  });\n  const rel=e=>{endCharge('btn'+e.pointerId);b.blur()};\n  b.addEventListener('pointerup',rel);\n  b.addEventListener('pointercancel',rel);\n  b.addEventListener('contextmenu',e=>e.preventDefault());\n  b.addEventListener('click',e=>{if(e.detail===0)swingYou(kind)}); // keyboard activation\n}\nbindSwing('btnDrive','drive');bindSwing('btnDink','dink');\n\n/* ---------- stick (phone layout) ---------- */\nconst mqPhone=window.matchMedia('(max-width:879px)');\nfunction stickOn(){return mqPhone.matches}\nfunction deck(){return 0}\nconst stickEl=$('stick'),knobEl=$('knob'),hintEl=$('stickHint'),courtEl=$('courtBox');\nlet stickId=null,sBase={x:0,y:0};\nfunction stickRelease(){\n  stickId=null;stickV.x=0;stickV.y=0;knobEl.style.transform='';\n  stickEl.classList.remove('on');hintEl.classList.remove('off');\n}\nfunction stickSet(e){\n  // The stick drags its own base along when the thumb goes past the ring, so reversing direction is instant.\n  const k=44;\n  let dx=e.clientX-sBase.x,dy=e.clientY-sBase.y,d=Math.hypot(dx,dy);\n  if(d>k){\n    const o=(d-k)/d;\n    sBase.x=clamp(sBase.x+dx*o,64,innerWidth-64);sBase.y=clamp(sBase.y+dy*o,64+60,innerHeight-64);\n    stickEl.style.left=sBase.x+'px';stickEl.style.top=sBase.y+'px';\n    dx=e.clientX-sBase.x;dy=e.clientY-sBase.y;d=Math.hypot(dx,dy);\n  }\n  const kd=Math.min(d,k);\n  const kx=d?dx/d*kd:0,ky=d?dy/d*kd:0;\n  knobEl.style.transform='translate('+kx.toFixed(1)+'px,'+ky.toFixed(1)+'px)';\n  // Small dead zone, full speed by about two thirds of the way out.\n  const m=kd/k,mag=clamp((m-.08)/(.62-.08),0,1);\n  stickV.x=d?dx/d*mag:0;stickV.y=d?dy/d*mag:0;\n}\n// Floating stick: touch the left part of the court and the stick appears right under the thumb.\ncourtEl.addEventListener('pointerdown',e=>{\n  if(!stickOn()||e.pointerType==='mouse'||S.paused||stickId!==null)return;\n  if(e.target.closest('button')||e.target.closest('.veil')||e.target.closest('.lobby'))return;\n  if(e.clientX>innerWidth*.62)return;\n  unlockAudio();\n  if(S.mode==='over'){requestNewGame();return}\n  e.preventDefault();stickId=e.pointerId;\n  try{courtEl.setPointerCapture(e.pointerId)}catch(_){}\n  sBase.x=clamp(e.clientX,64,innerWidth-64);sBase.y=clamp(e.clientY,64+60,innerHeight-64);\n  stickEl.style.left=sBase.x+'px';stickEl.style.top=sBase.y+'px';\n  stickEl.classList.add('on');hintEl.classList.add('off');\n  stickSet(e);\n});\ncourtEl.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickSet(e)});\n['pointerup','pointercancel','lostpointercapture'].forEach(t=>courtEl.addEventListener(t,e=>{if(e.pointerId===stickId)stickRelease()}));\nmqPhone.addEventListener&&mqPhone.addEventListener('change',()=>{stickRelease();layout()});\n$('btnMenu').addEventListener('click',()=>{\n  const t=document.querySelector('.top'),o=!t.classList.contains('open');\n  t.classList.toggle('open',o);$('btnMenu').setAttribute('aria-expanded',String(o));\n});\n\ndocument.querySelectorAll('[data-diff]').forEach(btn=>{\n  btn.addEventListener('click',()=>{\n    S.diff=btn.dataset.diff;\n    document.querySelectorAll('[data-diff]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));\n    btn.blur();\n  });\n});\n$('btnSound').addEventListener('click',e=>{\n  S.sound=!S.sound;e.currentTarget.setAttribute('aria-pressed',String(S.sound));\n  e.currentTarget.textContent=S.sound?'Sound on':'Sound off';e.currentTarget.blur();\n});\n$('btnNew').addEventListener('click',e=>{setPaused(false);requestNewGame();e.currentTarget.blur()});\n$('btnPause').addEventListener('click',e=>{togglePause();e.currentTarget.blur()});\n$('veil').addEventListener('click',()=>setPaused(false));\nfunction syncAuto(){\n  const b=$('btnAuto');\n  b.setAttribute('aria-pressed',String(S.auto));\n  b.textContent=S.auto?'Auto swing on':'Auto swing off';\n}\n$('btnAuto').addEventListener('click',e=>{S.auto=!S.auto;syncAuto();e.currentTarget.blur()});\nsyncAuto();\n\n/* ---------- online play (Supabase Realtime broadcast + presence) ---------- */\nconst SB_SRC='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.117.3/dist/umd/supabase.js';\nconst CODE_CHARS='ABCDEFGHJKMNPQRSTUVWXYZ';\nconst POS_HZ=15;\nconst num=v=>typeof v==='number'&&isFinite(v);\nconst cleanName=v=>(typeof v==='string'?v:'').replace(/\\s+/g,' ').trim().slice(0,16)||'Opponent';\nconst cleanCode=v=>String(v||'').toUpperCase().replace(/[^A-Z]/g,'').slice(0,4);\n\nfunction requestNewGame(){\n  if(MP.on)netSend({t:'new'});\n  newGame();\n}\nfunction netSend(m){\n  if(!MP.ch)return;\n  MP.ch.send({type:'broadcast',event:'m',payload:m}).catch(()=>{});\n}\nconst r3=v=>Math.round(v*1000)/1000;\nfunction packBall(){\n  const b=ball;\n  return[r3(b.x),r3(b.y),r3(b.z),r3(b.vx),r3(b.vy),r3(b.vz),r3(b.sp),r3(b.ax),r3(b.vis)];\n}\n// Mirror the opponent's ball into this client's view, then catch it up by half the ping.\nfunction applyBall(a){\n  if(!Array.isArray(a)||a.length!==9||!a.every(num))return false;\n  ball.x=CW-a[0];ball.y=CL-a[1];ball.z=a[2];\n  ball.vx=-a[3];ball.vy=-a[4];ball.vz=a[5];\n  ball.sp=-a[6];ball.ax=-a[7];ball.vis=-a[8];\n  let lead=Math.min(.2,MP.rtt/2);\n  const h=1/120;\n  while(lead>0&&S.mode==='rally'){stepBall(Math.min(h,lead));lead-=h}\n  return true;\n}\nfunction remoteSwing(n){\n  if(!num(n)||n===MP.swn)return;\n  MP.swn=n;\n  if(P.cpu.swing<=0){P.cpu.swing=SW;P.cpu.cool=0}\n}\nfunction onNet(m){\n  if(!m||typeof m.t!=='string')return;\n  if(m.t==='start'){if(MP.pending==='guest')startOnline('guest',m.name);return}\n  if(m.t==='ping'){netSend({t:'pong',ts:m.ts});return}\n  if(!MP.on)return;\n  switch(m.t){\n    case 'pos':\n      if(num(m.x)&&num(m.y)){P.cpu.gx=CW-m.x;P.cpu.gy=CL-m.y}\n      remoteSwing(m.n);\n      break;\n    case 'hit':\n      if(S.mode==='dead'&&!S.gameOver)setupPoint(); // they served before our replay timer ran out\n      if(S.mode==='ready'){S.mode='rally';setBanner(null)}\n      if(S.mode!=='rally'||!num(m.h))return;\n      S.hits=m.h;$('rally').textContent=S.hits;\n      ball.hitter='cpu';ball.bounces=0;ball.trail.length=0;\n      remoteSwing(m.n);\n      if(applyBall(m.b)){\n        S.fx.push({x:ball.x,y:ball.y-ball.z*.55,t:0});\n        pock(780,.07,.2);\n      }\n      break;\n    case 'spin':\n      if(S.mode==='rally'&&ball.hitter==='cpu'&&ball.bounces===0)applyBall(m.b);\n      break;\n    case 'pt': {\n      if(!Array.isArray(m.sc)||!m.sc.every(num))return;\n      if(S.mode==='rally')endPoint(m.w==='me'?'cpu':'you',String(m.why),true);\n      // Their call is final: take their score and server.\n      S.score.you=m.sc[1];S.score.cpu=m.sc[0];S.server=m.sv==='me'?'cpu':'you';\n      const a=S.score.you,c=S.score.cpu;\n      S.gameOver=Math.max(a,c)>=11&&Math.abs(a-c)>=2;\n      syncUI();\n      if(S.mode==='ready')setupPoint();\n      break;\n    }\n    case 'pause':setPaused(!!m.p,true);break;\n    case 'new':setPaused(false,true);newGame();break;\n    case 'pong':\n      if(num(m.ts)){\n        const r=Math.max(0,(performance.now()-m.ts)/1000);\n        MP.rtt=MP.rtt*.7+r*.3;\n        $('ping').textContent=Math.round(MP.rtt*1000)+' ms';\n      }\n      break;\n  }\n}\nfunction netUpdate(dt){\n  const c=P.cpu,k=Math.min(1,dt*14);\n  c.x+=(c.gx-c.x)*k;c.y+=(c.gy-c.y)*k;\n  MP.posT-=dt;\n  if(MP.posT<=0){\n    MP.posT=1/POS_HZ;\n    netSend({t:'pos',x:r3(P.you.x),y:r3(P.you.y),n:P.you.swn|0});\n  }\n}\n// Pings keep running while paused so the meter stays live.\nsetInterval(()=>{if(MP.on)netSend({t:'ping',ts:performance.now()})},2000);\n\nlet sbClient=null;\nfunction loadSupabase(){\n  if(sbClient)return sbClient;\n  sbClient=new Promise((res,rej)=>{\n    if(!CFG.url||!CFG.key){rej(new Error('Online play is not configured.'));return}\n    const s=document.createElement('script');\n    s.src=SB_SRC;s.async=true;s.crossOrigin='anonymous';\n    s.onload=()=>{\n      try{res(window.supabase.createClient(CFG.url,CFG.key,{auth:{persistSession:false,autoRefreshToken:false}}))}\n      catch(e){rej(e)}\n    };\n    s.onerror=()=>rej(new Error('Could not load the online service.'));\n    document.head.appendChild(s);\n  }).catch(e=>{sbClient=null;throw e});\n  return sbClient;\n}\nasync function openRoom(code){\n  const sb=await loadSupabase();\n  await closeRoom();\n  const ch=sb.channel('kitchen-line:'+code,{config:{broadcast:{self:false,ack:false},presence:{key:MP.id}}});\n  MP.ch=ch;MP.room=code;MP.peers=[];MP.synced=false;MP.tracked=false;\n  ch.on('broadcast',{event:'m'},({payload})=>{if(MP.ch===ch)onNet(payload)});\n  ch.on('presence',{event:'sync'},()=>{if(MP.ch===ch)onPresence()});\n  await new Promise((res,rej)=>{\n    let done=false;\n    ch.subscribe((status)=>{\n      if(status==='SUBSCRIBED'&&!done){done=true;res()}\n      else if((status==='CHANNEL_ERROR'||status==='TIMED_OUT')&&!done){done=true;rej(new Error('Could not connect. Check your connection and try again.'))}\n      else if(status==='CHANNEL_ERROR'&&MP.on)showHint('Connection dropped. Reconnecting…',2.5);\n    });\n  });\n}\nasync function closeRoom(){\n  const ch=MP.ch;MP.ch=null;MP.peers=[];MP.synced=false;MP.tracked=false;\n  if(ch){try{await ch.unsubscribe()}catch(e){}try{(await sbClient).removeChannel(ch)}catch(e){}}\n}\nfunction waitSync(ms){\n  return new Promise(res=>{\n    const t0=performance.now();\n    const step=()=>{if(MP.synced||performance.now()-t0>ms)res();else setTimeout(step,60)};\n    step();\n  });\n}\nfunction onPresence(){\n  const st=MP.ch.presenceState(),peers=[];\n  for(const k in st){if(k!==MP.id&&st[k]&&st[k][0])peers.push(st[k][0])}\n  MP.peers=peers;MP.synced=true;\n  const want=MP.role==='host'?'guest':'host';\n  if(MP.on){\n    if(!peers.some(p=>p.role===want))opponentLeft();\n    return;\n  }\n  if(MP.pending==='host'&&MP.tracked){\n    const g=peers.find(p=>p.role==='guest');\n    if(g){netSend({t:'start',name:MP.name});startOnline('host',g.name)}\n  }\n}\n\nfunction startOnline(role,oppName){\n  MP.on=true;MP.role=role;MP.pending='';MP.swn=0;MP.posT=0;P.you.swn=0;\n  NAME.cpu=cleanName(oppName);\n  document.body.classList.add('net-on');\n  $('roomCode').textContent=MP.room;$('netMeta').hidden=false;$('ping').textContent='–';\n  $('btnOnline').textContent='Leave online game';\n  $('cv').setAttribute('aria-label','Top-down pickleball court. You are at the bottom, '+NAME.cpu+' at the top.');\n  hideLobby();\n  S.paused=false;$('veil').hidden=true;\n  $('btnPause').setAttribute('aria-pressed','false');$('btnPause').setAttribute('aria-label','Pause');\n  newGame();\n  showHint('Playing '+NAME.cpu+' · room '+MP.room,2.4);\n  netSend({t:'ping',ts:performance.now()});\n}\nasync function leaveOnline(){\n  const wasOn=MP.on;\n  MP.on=false;MP.role='';MP.pending='';\n  await closeRoom();\n  NAME.cpu='CPU';\n  document.body.classList.remove('net-on');\n  $('netMeta').hidden=true;$('btnOnline').textContent='Play online';\n  $('cv').setAttribute('aria-label','Top-down pickleball court. You are at the bottom, the CPU at the top.');\n  if(wasOn){setPaused(false);newGame()}\n}\nasync function opponentLeft(){\n  const who=NAME.cpu;\n  await leaveOnline();\n  openLobby(who+' left the game.');\n}\n\n/* ---------- lobby UI ---------- */\nfunction lobbyView(view){\n  $('lobMenu').hidden=view!=='menu';$('lobWait').hidden=view!=='wait';\n  $('lobTitle').textContent=view==='wait'?'Your room':'Play online';\n}\nfunction lobbyBusy(b){['lobCreate','lobJoinBtn'].forEach(id=>{$(id).disabled=b})}\nfunction lobbyError(msg){$('lobErr').textContent=msg||''}\nfunction openLobby(msg){\n  cancelCharge();\n  S.lobby=true;\n  lobbyView('menu');lobbyBusy(false);lobbyError(msg);\n  $('lobby').hidden=false;\n  $('lobName').value=MP.name==='Player'?'':MP.name;\n  setTimeout(()=>{(msg?$('lobCode'):$('lobName')).focus()},0);\n}\nfunction hideLobby(){S.lobby=false;$('lobby').hidden=true}\nasync function closeLobby(){\n  if(MP.pending){MP.pending='';await closeRoom()}\n  hideLobby();\n  $('btnOnline').focus();\n}\nfunction readName(){\n  MP.name=cleanName($('lobName').value)==='Opponent'?'Player':cleanName($('lobName').value);\n  try{localStorage.setItem('kl-name',MP.name)}catch(e){}\n}\nasync function createRoom(){\n  readName();lobbyBusy(true);lobbyError('');\n  try{\n    for(let i=0;i<5;i++){\n      let code='';for(let j=0;j<4;j++)code+=CODE_CHARS[Math.floor(Math.random()*CODE_CHARS.length)];\n      await openRoom(code);\n      await waitSync(1200);\n      if(MP.peers.length){await closeRoom();continue} // code already in use\n      MP.pending='host';MP.role='host';MP.tracked=true;\n      await MP.ch.track({role:'host',name:MP.name});\n      $('lobRoom').textContent=code;\n      $('lobCopy').textContent='Copy invite link';\n      lobbyView('wait');\n      $('lobCopy').focus();\n      return;\n    }\n    throw new Error('Could not find a free room. Try again.');\n  }catch(e){\n    MP.pending='';await closeRoom();\n    lobbyError(e&&e.message||'Something went wrong. Try again.');\n  }finally{lobbyBusy(false)}\n}\nasync function joinRoom(raw){\n  const code=cleanCode(raw);\n  if(code.length!==4){lobbyError('Enter the four-letter room code.');$('lobCode').focus();return}\n  readName();lobbyBusy(true);lobbyError('');\n  try{\n    await openRoom(code);\n    await waitSync(3000);\n    if(!MP.peers.some(p=>p.role==='host'))throw new Error('No game found with code '+code+'.');\n    if(MP.peers.some(p=>p.role==='guest'))throw new Error('That game already has two players.');\n    MP.pending='guest';MP.role='guest';\n    await MP.ch.track({role:'guest',name:MP.name});\n    setTimeout(()=>{ // the host answers with 'start' as soon as it sees us\n      if(MP.pending==='guest'&&!MP.on){MP.pending='';closeRoom();lobbyError('The host did not respond. Try again.');lobbyBusy(false)}\n    },6000);\n  }catch(e){\n    MP.pending='';await closeRoom();\n    lobbyError(e&&e.message||'Something went wrong. Try again.');\n    lobbyBusy(false);\n  }\n}\nfunction inviteLink(){\n  const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('room',MP.room);\n  return u.toString();\n}\n$('btnOnline').addEventListener('click',e=>{\n  e.currentTarget.blur();\n  if(MP.on)leaveOnline();else openLobby();\n});\n$('lobClose').addEventListener('click',()=>closeLobby());\n$('lobCancel').addEventListener('click',()=>{closeLobby()});\n$('lobCreate').addEventListener('click',()=>createRoom());\n$('lobJoin').addEventListener('submit',e=>{e.preventDefault();joinRoom($('lobCode').value)});\n$('lobCode').addEventListener('input',e=>{const v=cleanCode(e.target.value);if(v!==e.target.value)e.target.value=v});\n$('lobCopy').addEventListener('click',async e=>{\n  const b=e.currentTarget,link=inviteLink();\n  try{await navigator.clipboard.writeText(link);b.textContent='Link copied'}\n  catch(_){b.textContent='Copy blocked. Share the code.'}\n});\ntry{const n=localStorage.getItem('kl-name');if(n)MP.name=cleanName(n)}catch(e){}\naddEventListener('pagehide',()=>{if(MP.ch)closeRoom()});\n{\n  const q=new URLSearchParams(location.search).get('room');\n  if(q){\n    const u=new URL(location.href);u.searchParams.delete('room');\n    try{history.replaceState(null,'',u.toString())}catch(e){}\n    openLobby();\n    $('lobCode').value=cleanCode(q);\n    $('lobName').focus();\n  }\n}\n\n/* ---------- boot ---------- */\nlet last=0;\nfunction frame(ts){\n  const dt=Math.min(.05,Math.max(0,(ts-last)/1000)||0);last=ts;\n  if(!S.paused&&!S.lobby)update(dt);\n  render();\n  requestAnimationFrame(frame);\n}\naddEventListener('resize',layout);\nlayout();\nif(document.fonts&&document.fonts.ready)document.fonts.ready.then(layout);\nsetupPoint();\nif(window.__KL_TEST)window.__KL_TEST({S,P,ball,swingYou,update,render,keys,charge,beginCharge,endCharge,strike});\nrequestAnimationFrame(ts=>{last=ts;frame(ts)});\n})();\n</script>\n</body>\n</html>\n"
